const fs = require("node:fs");

module.exports = (api) => {
  const base = () =>
    String(api.settings.baseUrl || "http://127.0.0.1:49374").replace(/\/+$/, "");
  const defaultModel = () =>
    String(api.settings.defaultModel || "opencode/deepseek-v4.1-flash");
  const passwordFile = () =>
    String(api.settings.passwordFile || "/opt/iobroker/opencode-password");
  const chatDirectory = () =>
    String(api.settings.chatDirectory || "/home/pi/ihome-probe");
  const headers = () => ({
    authorization:
      "Basic " +
      Buffer.from(
        "opencode:" + fs.readFileSync(passwordFile(), "utf8").trim(),
      ).toString("base64"),
    "content-type": "application/json",
  });

  async function request(path, init, timeoutMs) {
    const res = await fetch(base() + path, {
      ...init,
      headers: { ...headers(), ...(init && init.headers ? init.headers : {}) },
      signal: AbortSignal.timeout(timeoutMs || 25000),
    });
    const text = await res.text();
    if (!res.ok)
      throw new Error("OpenCode HTTP " + res.status + ": " + text.slice(0, 300));
    return text ? JSON.parse(text) : null;
  }

  function modelRef(value) {
    if (
      value &&
      typeof value === "object" &&
      typeof value.providerID === "string" &&
      typeof value.id === "string"
    )
      return value;
    const text = String(value || defaultModel());
    const slash = text.indexOf("/");
    if (slash < 1) throw new Error("model must be provider/id");
    return { providerID: text.slice(0, slash), id: text.slice(slash + 1) };
  }

  // Session name -> id for this adapter process. Pass sessionID to resume a
  // session across restarts; reset: true starts a new one.
  const sessions = new Map();

  const sessionPath = (id, suffix) =>
    "/api/session/" + encodeURIComponent(id) + suffix;

  // Read-only chat sessions: broad allow, then explicit denies (last match wins).
  const READ_ONLY = [
    { action: "*", resource: "*", effect: "allow" },
    { action: "read", resource: "*.env*", effect: "deny" },
    { action: "edit", resource: "*", effect: "deny" },
    { action: "shell", resource: "*", effect: "deny" },
    { action: "subagent", resource: "*", effect: "deny" },
    { action: "execute", resource: "*", effect: "deny" },
    { action: "question", resource: "*", effect: "deny" },
    { action: "iobroker_set_*", resource: "*", effect: "deny" },
    { action: "iobroker_create_*", resource: "*", effect: "deny" },
    { action: "iobroker_delete_*", resource: "*", effect: "deny" },
    { action: "iobroker_write_*", resource: "*", effect: "deny" },
    { action: "iobroker_rename_*", resource: "*", effect: "deny" },
    { action: "iobroker_clear_*", resource: "*", effect: "deny" },
    { action: "iobroker_mkdir", resource: "*", effect: "deny" },
    { action: "iobroker_prepare_upload", resource: "*", effect: "deny" },
  ];

  async function createSession(model) {
    const json = await request("/api/session", {
      method: "POST",
      body: JSON.stringify({
        title: "iHome",
        location: { directory: chatDirectory() },
        model,
        permissions: READ_ONLY,
      }),
    });
    const id = json && json.data && json.data.id;
    if (!id) throw new Error("OpenCode returned no session id");
    return id;
  }

  async function switchModel(sessionID, model) {
    await request(sessionPath(sessionID, "/model"), {
      method: "POST",
      body: JSON.stringify({ model }),
    });
  }

  async function promptSession(sessionID, text) {
    await request(sessionPath(sessionID, "/prompt"), {
      method: "POST",
      body: JSON.stringify({ text }),
    });
  }

  function isTimeout(error) {
    return (
      Boolean(error) &&
      (error.name === "TimeoutError" || error.name === "AbortError")
    );
  }

  async function waitIdle(sessionID, ms) {
    try {
      await request(
        "/api/experimental/session/" + encodeURIComponent(sessionID) + "/wait",
        { method: "POST" },
        ms,
      );
      return true;
    } catch (error) {
      if (isTimeout(error)) return false;
      throw error;
    }
  }

  function textOf(message) {
    const content =
      message && Array.isArray(message.content) ? message.content : [];
    return content
      .filter(
        (part) => part && part.type === "text" && typeof part.text === "string",
      )
      .map((part) => part.text)
      .join("\n")
      .trim();
  }

  function countTools(message) {
    const content =
      message && Array.isArray(message.content) ? message.content : [];
    return content.filter((part) => part && part.type === "tool").length;
  }

  // Newest assistant text plus tool calls of every step since the given time.
  async function assistantReply(sessionID, since) {
    const json = await request(
      sessionPath(sessionID, "/message?type=assistant&order=desc&limit=20"),
    );
    const messages = json && Array.isArray(json.data) ? json.data : [];
    let toolCalls = 0;
    for (const message of messages) {
      const created = message && message.time && message.time.created;
      if (
        typeof since === "number" &&
        typeof created === "number" &&
        created < since
      )
        continue;
      toolCalls += countTools(message);
    }
    return { text: messages.length ? textOf(messages[0]) : "", toolCalls };
  }

  // When the current user turn started, so chatStatus counts only its tools.
  async function newestUserTime(sessionID) {
    const json = await request(
      sessionPath(sessionID, "/message?type=user&order=desc&limit=1"),
    );
    const message = json && Array.isArray(json.data) ? json.data[0] : null;
    return message && message.time && typeof message.time.created === "number"
      ? message.time.created
      : undefined;
  }

  // Wait for the loop to idle, then read the newest assistant message.
  async function chatReply(sessionID, since, waitMs) {
    const idle = await waitIdle(sessionID, waitMs);
    let reply = await assistantReply(sessionID, since);
    if (idle && !reply.text) {
      await new Promise((resolve) => setTimeout(resolve, 400));
      reply = await assistantReply(sessionID, since);
    }
    return { idle, reply };
  }

  return {
    async call(payload) {
      const req = payload && typeof payload === "object" ? payload : {};
      const action = typeof req.action === "string" ? req.action : "status";
      if (action === "status") return await request("/api/info");
      if (action === "models") {
        const json = await request("/api/model");
        return {
          models: (json.data || json).map((m) => ({
            providerID: m.providerID,
            id: m.id,
            name: m.name,
            variants: (m.variants || []).map((v) => v.id),
          })),
        };
      }
      if (action === "ask") {
        if (typeof req.prompt !== "string" || !req.prompt.trim())
          throw new Error("ask needs a prompt");
        const ref = modelRef(req.model);
        const started = Date.now();
        const json = await request("/api/experimental/generate/text", {
          method: "POST",
          body: JSON.stringify({ prompt: req.prompt, model: ref }),
        });
        return {
          text: String((json && json.data && json.data.text) || ""),
          model: ref,
          ms: Date.now() - started,
        };
      }
      if (action === "chat") {
        if (typeof req.prompt !== "string" || !req.prompt.trim())
          throw new Error("chat needs a prompt");
        const name =
          typeof req.session === "string" && req.session ? req.session : "default";
        let sessionID =
          typeof req.sessionID === "string" && req.sessionID
            ? req.sessionID
            : sessions.get(name);
        let model;
        if (!sessionID || req.reset === true) {
          model = modelRef(req.model);
          sessionID = await createSession(model);
          sessions.set(name, sessionID);
        } else if (req.model) {
          model = modelRef(req.model);
          await switchModel(sessionID, model);
        }
        const waitMs = Math.min(
          Math.max(Number(req.waitMs) || 20000, 1000),
          25000,
        );
        const started = Date.now();
        await promptSession(sessionID, req.prompt);
        const { idle, reply } = await chatReply(sessionID, started, waitMs);
        return {
          sessionID,
          status: idle ? "idle" : "running",
          text: reply.text,
          toolCalls: reply.toolCalls,
          ...(model ? { model } : {}),
          ms: Date.now() - started,
        };
      }
      if (action === "chatStatus") {
        const name =
          typeof req.session === "string" && req.session ? req.session : "default";
        const sessionID =
          typeof req.sessionID === "string" && req.sessionID
            ? req.sessionID
            : sessions.get(name);
        if (!sessionID) throw new Error("chatStatus needs a sessionID");
        const waitMs = Math.min(Math.max(Number(req.waitMs) || 2000, 500), 5000);
        const since = await newestUserTime(sessionID);
        const idle = await waitIdle(sessionID, waitMs);
        const reply = await assistantReply(sessionID, since);
        return {
          sessionID,
          status: idle ? "idle" : "running",
          text: reply.text,
          toolCalls: reply.toolCalls,
        };
      }
      throw new Error("unknown OpenCode action: " + action);
    },
  };
};
